// A store whose only session, the one u1 had, outlived its one-millisecond lifetime before anyone asked for it.
const agedOut = async (): Promise<InMemorySessionStore> => {
  const store = new InMemorySessionStore({maxAgeMs: 1});
  const {entries} = store.create('known', 'u1');
  entries.push({role: 'user', content: 'my booking 4711', timestamp: '2026-09-30T08:00:00.000Z'});
  await new Promise(resolve => setTimeout(resolve, 20));
  return store;
};

describe('telling an expired session apart', () => {
  it('tells the owner of a session that aged out that it expired, with a new id and no replay', async () => {
    const {base} = await startEngine(await agedOut(), RESUME_ON);

    const frames = await connectAndSettle(`${base}?sessionId=known`);

    expect({
      connected: frames[0],
      minted: frames[0].sessionId !== 'known',
      replayed: upserts(frames).length,
    }).toMatchObject({
      connected: {resumed: false, resumeFailure: 'expired'},
      minted: true,
      replayed: 0,
    });
  });

  it('answers another user naming an expired id exactly as it answers an id never issued', async () => {
    const {auth, base} = await startEngine(await agedOut(), RESUME_ON);
    auth.userId = 'u2';

    const expired = await connectAndSettle(`${base}?sessionId=known`);
    const neverIssued = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);

    expect({expired: shapeOf(expired), failure: expired[0].resumeFailure}).toEqual({
      expired: shapeOf(neverIssued),
      failure: 'unknown',
    });
  });

  it('sends no resumeFailure at all when the connect names no id, even with no latest session to rejoin', async () => {
    const {base} = await startEngine(new InMemorySessionStore(), LATEST_ON);

    const [connected] = await connectAndSettle(base);

    expect({resumed: connected.resumed, failureKey: 'resumeFailure' in connected}).toEqual({
      resumed: false,
      failureKey: false,
    });
  });

  it('reads a named id with one call per attempt: lookup when the store has it, get otherwise', async () => {
    const inner = storeWith([['known', 'u1', '2026-09-30T08:00:00.000Z']]);
    const calls: string[] = [];
    const fiveMembers: SessionStore = {
      ...delegatingTo(inner),
      get: sessionId => {
        calls.push('get');
        return inner.get(sessionId);
      },
    };
    const withLookup: SessionStore = {
      ...fiveMembers,
      lookup: sessionId => {
        calls.push('lookup');
        return inner.lookup(sessionId);
      },
    };

    const outcomes: Record<string, unknown> = {};
    for (const [name, store] of Object.entries({fiveMembers, withLookup})) {
      const {base} = await startEngine(store, RESUME_ON);
      const [live] = await connectAndSettle(`${base}?sessionId=known`);
      const [dead] = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);
      outcomes[name] = {live: live.resumed, dead: dead.resumeFailure};
    }

    const answered = {live: true, dead: 'unknown'};
    expect({outcomes, calls}).toEqual({
      outcomes: {fiveMembers: answered, withLookup: answered},
      calls: ['get', 'get', 'lookup', 'lookup'],
    });

import {WebSocket} from 'ws';
import type {SessionEntry} from '../../types/session.js';
import type {ChatSession} from '../../types/session.js';
import {ErrorCodes} from '../../types/messages.js';
import type {OutgoingMessage} from '../../types/messages.js';
import type {ListSessionsMessage, SessionSummaryFrame} from '../../types/messages.js';
import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
import {validateMessage} from './validation.js';
import type {ValidationResult} from './validation.js';
import {PerSessionLock} from '../../shared/perSessionLock.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import {AIError} from '../../types/ai.js';
import type {MessageChunk} from '../../types/ai.js';
import {
  createUserEntry,
  createAssistantEntry,
  createThinkingEntry,
  createToolEntry,
} from '../../orchestration/entryFactories.js';
import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
import {log} from '../../shared/logger.js';
import type {SessionStore} from '../../types/sessionStore.js';

interface StreamState {
  thinkingIndex: number | null;
  assistantIndex: number | null;
  suppressOutput: boolean;
  sentAssistantIndices: number[];
}

type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  return function handleMessage(
    ws: WebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
    }
    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
    return wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore));
  };
}

// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
async function answerInTurn(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
    return;
  }
  const startedAt = Date.now();
  try {
    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
  } finally {
    endTurn(ws, session, signal, startedAt);
  }
}

// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
  if (signal?.aborted) {
    log.info('message', 'turn abandoned: its socket closed', {
      sessionId: session.sessionId,
      elapsedMs: Date.now() - startedAt,
    });
    return;
  }
  sendStreamEnd(ws);
}

async function answerUserMessage(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  const message = validation.valid ? validation.data : undefined;
  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
  answerFrame(ws, session, validation, sessionStore);
}

async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  validation: ValidationResult,
  sessionStore?: SessionStore
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') await answerSessionList(ws, session, sessionStore, message);
}

async function answerSessionList(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  try {
    const summaries = (await sessionStore?.listFor?.(session.userId, {
      limit: message.limit,
      before: message.before,
    })) ?? [];
    const sessions: SessionSummaryFrame[] = summaries.map(summary => ({
      ...summary,
      createdAt: summary.createdAt.toISOString(),
      updatedAt: summary.updatedAt.toISOString(),
    }));
    sendSessionList(ws, sessions);
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'conversation list failed', {sessionId: session.sessionId, userId: session.userId, error: message});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
function isUserMessageFrame(rawMessage: unknown): boolean {
  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
}

